KATA_TAHSIN = ["nun mati","nun sukun","mim mati","mad wajib","mad lazim","mad jaiz","mad arid","qolqolah","qalqalah","ghunnah","tafkhim","tarqiq","makhroj","makhraj","sifat huruf","izhar","ikhfa","iqlab","idgham","lam syamsiyah","lam qomariyah","waqof","tajwid","tahsin","lahn","talaqqi","musyafahah","istilah tahsin","evaluasi tahsin","tips tahsin","pengertian tahsin","bedanya tahsin","tujuan tahsin","dasar hukum","keutamaan baca","metode tahsin","tahapan tahsin","praktik al-fatihah","referensi tahsin"]
