KATA_IQRO = ["iqro","hijaiyah","huruf mirip","fathah","kasroh","kasrah","dhommah","dhammah","harokat","harakat","tanwin","sukun","tasydid","qamariyah","qomariyah","syamsiyah","makhroj iqro","sifat huruf iqro","mad iqro","tanda baca","metode iqro","evaluasi iqro","kesalahan iqro","program iqro","soal iqro","kiat iqro","adab belajar","pengertian iqro","tujuan iqro","prinsip iqro","huruf bersambung","latihan al-fatihah","latihan al-ikhlas","latihan al-falaq"]
# ================= IQRO =================
def jawab_iqro(t,n):
    if t in ["iqro","materi iqro","apa itu iqro","pengertian iqro"]:
        return f"**MATERI IQRO SUPER LENGKAP BAB I-XX, {n}! 📖**\n\nBAB I Pengenalan: Ketik Pengertian iqro / Tujuan iqro / Prinsip iqro\nBAB II Huruf: Ketik Huruf Hijaiyah / Huruf mirip\nBAB III Iqro 1: Ketik Iqro 1 / Fathah\nBAB IV Iqro 2: Ketik Iqro 2 / Huruf bersambung\nBAB V Iqro 3: Ketik Iqro 3 / Kasrah / Dhammah\nBAB VI Iqro 4: Ketik Iqro 4 / Sukun / Tanwin\nBAB VII Iqro 5: Ketik Iqro 5 / Tasydid / Qamariyah\nBAB VIII Iqro 6: Ketik Iqro 6 / Nun mati / Mim mati / Qolqolah\nBAB IX Makhroj: Ketik Makhroj Iqro\nBAB X Sifat: Ketik Sifat huruf Iqro\nBAB XI Mad: Ketik Mad Iqro\nBAB XII Tanda Baca: Ketik Tanda baca\nBAB XIII Latihan: Ketik Latihan Al-Fatihah\nBAB XIV Metode: Ketik Metode Iqro\nBAB XV Evaluasi: Ketik Evaluasi Iqro\nBAB XVI Kesalahan: Ketik Kesalahan Iqro\nBAB XVII Program: Ketik Program Iqro\nBAB XVIII Soal: Ketik Soal Iqro\nBAB XIX Kiat: Ketik Kiat Iqro\nBAB XX Adab: Ketik Adab belajar"
    if "pengertian iqro" in t: return f"**BAB I - PENGERTIAN IQRO', {n}**\n\nIqro' adalah metode belajar baca Quran karya **KH. As'ad Humam Yogyakarta**. Bertahap: kenal bentuk & bunyi huruf -> huruf berharakat -> huruf bersambung -> bentuk bacaan Quran. Menekankan talaqqi, latihan, pengulangan, peningkatan bertahap."
    if "tujuan iqro" in t: return f"**BAB I - TUJUAN IQRO', {n}**\n\n1.Kenal semua huruf hijaiyah 2.Kenal makhroj 3.Baca huruf sesuai harakat 4.Baca huruf bersambung 5.Baca panjang & pendek 6.Kenal tanda baca Quran 7.Biasa baca benar & lancar 8.Siap baca Quran dengan tajwid"
    if "prinsip iqro" in t: return f"**BAB I - PRINSIP IQRO', {n}**\n\n1.Bertahap - sederhana ke kompleks 2.Langsung praktik - bukan cuma teori 3.Individual - guru perhatikan tiap anak 4.Pengulangan - ulang sampai paham 5.Tidak tergesa-gesa - jangan lanjut kalau belum cukup 6.Talaqqi & Musyafahah - guru contoh, murid tiru sambil perhatikan mulut guru"
    if "huruf hijaiyah" in t or "hijaiyah" in t: return f"**BAB II - HURUF HIJAIYAH 29 HURUF, {n}**\n\n1 ا Alif, 2 ب Ba, 3 ت Ta, 4 ث Tsa, 5 ج Jim, 6 ح Ha tenggorokan, 7 خ Kha, 8 د Dal, 9 ذ Dzal, 10 ر Ra, 11 ز Zai, 12 س Sin, 13 ش Syin, 14 ص Shad, 15 ض Dhad, 16 ط Tha, 17 ظ Zha, 18 ع 'Ain, 19 غ Ghain, 20 ف Fa, 21 ق Qaf, 22 ك Kaf, 23 ل Lam, 24 م Mim, 25 ن Nun, 26 و Wau, 27 ه Ha, 28 ء Hamzah, 29 ي Ya\n\nCatatan: Pelafalan hanya pendekatan awal. Yang benar harus lewat Makhroj & Sifat."
    if "huruf mirip" in t: return f"**BAB II - HURUF MIRIP, {n}**\n\nBa: ب ت ث | Jim: ج ح خ | Dal: د ذ | Ra: ر ز | Sin: س ش | Shad: ص ض | Tha: ط ظ | 'Ain: ع غ | Fa: ف ق\n\nLatihan: Guru tunjuk acak, murid sebut nama. Tujuannya bukan hafal urutan, tapi kenal huruf acak!"
    if "iqro 1" in t: return f"**BAB III - IQRO 1, {n}**\n\nTujuan: Kenal huruf, baca Fathah, bedain bunyi, baca urut & acak.\n\n**FATHAH (َ)** = garis di ATAS, bunyi /a/ pendek.\n\nبَ=Ba, تَ=Ta, ثَ=Tsa, جَ=Ja, حَ=Ha, خَ=Kha, دَ=Da, ذَ=Dza, رَ=Ra, زَ=Za, سَ=Sa, شَ=Sya, صَ=Sha, ضَ=Dha, طَ=Tha, ظَ=Zha, عَ='A, غَ=Gha, فَ=Fa, قَ=Qa, كَ=Ka, لَ=La, مَ=Ma, نَ=Na, وَ=Wa, هَ=Ha, ءَ=A, يَ=Ya\n\nLatihan: بَ تَ ثَ جَ حَ خَ / دَ ذَ رَ زَ سَ شَ / صَ ضَ طَ ظَ عَ غَ / فَ قَ كَ لَ مَ نَ / وَ هَ ءَ يَ\n\nAcak: قَ بَ مَ تَ رَ شَ / عَ دَ فَ خَ لَ صَ / يَ غَ نَ ثَ زَ كَ\n\nLulus: Bisa baca semua Fathah tanpa hafal urutan!"
    if "fathah" in t: return f"**FATHAH (َ), {n}**\n\nGaris di ATAS huruf, bunyi /a/ pendek. Contoh: بَ=Ba, تَ=Ta, جَ=Ja. Latihan: بَ تَ ثَ جَ حَ خَ. Materi Iqro 1."
    if "iqro 2" in t or "huruf bersambung" in t: return f"**BAB IV - IQRO 2, {n}**\n\nTujuan: Baca Fathah bersambung, baca rangkaian benar, paham bentuk awal-tengah-akhir, baca tanpa mengeja satu-satu.\n\n**Bersambung:** ب -> بـ - ـبـ - ـب, ت -> تـ - ـتـ - ـت, س -> سـ - ـسـ - ـس, ع -> عـ - ـعـ - ـع, ك -> كـ - ـكـ - ـك\n\n**TIDAK menyambung ke depannya:** ا د ذ ر ز و\n\nLatihan: بَتَ=Ba-ta, تَبَ=Ta-ba, جَبَ=Ja-ba, سَمَ=Sa-ma, كَتَبَ=Ka-ta-ba, نَزَلَ=Na-za-la, دَخَلَ=Da-kha-la, خَرَجَ=Kha-ra-ja\n\nRangkaian: بَتَثَ, جَحَخَ, دَذَرَ, سَمَكَ, كَتَبَ, نَصَرَ\n\nLulus: Baca bersambung LANCAR, tidak putus-putus!"
    if "iqro 3" in t: return f"**BAB V - IQRO 3, {n}**\n\nTujuan: Kenal Kasrah, Dhammah, baca 3 harakat, bedain Fathah-Kasrah-Dhammah.\n\n**KASRAH (ِ)** = garis di BAWAH, bunyi /i/. Contoh: بِ=Bi, تِ=Ti, جِ=Ji, سِ=Si, مِ=Mi, نِ=Ni\n\n**DHAMMAH (ُ)** = waw kecil di ATAS, bunyi /u/. Contoh: بُ=Bu, تُ=Tu, جُ=Ju, سُ=Su, مُ=Mu, نُ=Nu\n\nPerbandingan: بَ Ba, بِ Bi, بُ Bu | تَ Ta, تِ Ti, تُ Tu | جَ Ja, جِ Ji, جُ Ju | سَ Sa, سِ Si, سُ Su | مَ Ma, مِ Mi, مُ Mu | نَ Na, نِ Ni, نُ Nu | كَ Ka, كِ Ki, كُ Ku | لَ La, لِ Li, لُ Lu\n\nLatihan: بَ بِ بُ - تَ تِ تُ - جَ جِ جُ - سَ سِ سُ - مَ مِ مُ - نَ نِ نُ"
    if "kasrah" in t or "kasroh" in t: return f"**KASRAH (ِ), {n}**\n\nGaris di BAWAH huruf, bunyi /i/ pendek. Contoh: بِ=Bi, تِ=Ti. Latihan: بِ تِ ثِ جِ حِ خِ. Materi Iqro 3."
    if "dhammah" in t or "dhommah" in t: return f"**DHAMMAH (ُ), {n}**\n\nWaw kecil di ATAS huruf, bunyi /u/ pendek. Contoh: بُ=Bu, تُ=Tu. Latihan: بُ تُ ثُ جُ حُ خُ. Materi Iqro 3."
    if "iqro 4" in t: return f"**BAB VI - IQRO 4, {n}**\n\nTujuan: Kenal Sukun, baca huruf mati, kenal Mad, kenal Tanwin, baca kombinasi harakat.\n\n**SUKUN (ْ)** = huruf mati. Contoh: بْ=B mati, مْ=M mati. Cara: Sambung ke huruf sebelumnya. أَبْ=Ab, أَتْ=At, أَمْ=Am, أَنْ=An, أَلْ=Al. Latihan: اَبْ تَ, اَكْ تَ, اَمْ سَ, اَنْ تَ\n\n**MAD THABI'I** = Panjang asli 2 harakat. Huruf Mad: Alif setelah Fathah, Ya sukun setelah Kasrah, Waw sukun setelah Dhammah. Contoh: بَا=Baa, بِي=Bii, بُو=Buu, قَالَ, يَقُولُ, قِيلَ. Beda: بَ vs بَا, بِ vs بِي, بُ vs بُو\n\n**TANWIN** = bunyi /n/ akhir kata. Fathatain (ً): بًا=Ban. Kasratain (ٍ): بٍ=Bin. Dhammatain (ٌ): بٌ=Bun. Latihan: بًا بٍ بٌ, كِتَابًا, عَلِيمٌ, سَمِيعٌ\n\nLulus: Bisa baca Sukun, Mad, Tanwin benar!"
    if "sukun" in t: return f"**SUKUN (ْ), {n} - Iqro 4**\n\nHuruf mati. Sambung ke huruf sebelumnya. Contoh: أَبْ=Ab, أَمْ=Am, أَنْ=An. Latihan: اَبْ تَ, اَمْ سَ"
    if "tanwin" in t: return f"**TANWIN, {n} - Iqro 4**\n\nBunyi /n/ akhir kata. Fathatain=AN: بًا=Ban, Kasratain=IN: بٍ=Bin, Dhammatain=UN: بٌ=Bun. Latihan: كِتَابًا, عَلِيمٌ"
    if "iqro 5" in t: return f"**BAB VII - IQRO 5, {n}**\n\nTujuan: Baca Tasydid, paham Tasydid, kenal Qamariyah, kenal Syamsiyah, baca kombinasi tanda baca.\n\n**TASYDID (ّ)** = kepala sin kecil di atas, huruf rangkap / ditekan. Teori: 2 huruf sama, pertama sukun, kedua berharakat. Contoh: بَّ=Bba, مَّ=Mma, نَّ=Nna. Kata: إِنَّ, اَللّٰهُ, رَبِّ, ثُمَّ, مُحَمَّدٌ, وَالنَّاسِ\n\n**QAMARIYAH** = Lam dibaca JELAS. Huruf 14: ا ب ج ح خ ع غ ف ق ك م ه و ي. Contoh: الْقَمَرُ, الْكِتَابُ, الْحَمْدُ, الْعَلِيمُ\n\n**SYAMSIYAH** = Lam TIDAK dibaca, melebur. Huruf 14: ت ث د ذ ر ز س ش ص ض ط ظ ل ن. Contoh: الشَّمْسُ, النَّاسُ, الرَّحْمٰنُ, التَّوْبَةُ\n\nBeda: Qamariyah: Lam jelas, ada sukun di Lam, Al-Qamar. Syamsiyah: Lam tidak dibaca, huruf setelah Lam tasydid, Asy-Syams."
    if "tasydid" in t: return f"**TASYDID (ّ), {n} - Iqro 5**\n\nHuruf rangkap / ditekan. Contoh: إِنَّ=Inna, رَبِّ=Robbi, ثُمَّ=Tsumma, مُحَمَّدٌ=Muhammadun"
    if "qamariyah" in t or "qomariyah" in t: return f"**QAMARIYAH, {n} - Iqro 5**\n\nLam dibaca JELAS. Huruf 14: ا ب ج ح خ ع غ ف ق ك م ه و ي. Contoh: الْقَمَرُ=Al-Qamar, الْكِتَابُ=Al-Kitab"
    if "syamsiyah" in t: return f"**SYAMSIYAH, {n} - Iqro 5**\n\nLam TIDAK dibaca, melebur. Huruf 14: ت ث د ذ ر ز س ش ص ض ط ظ ل ن. Contoh: الشَّمْسُ=Asy-Syams, النَّاسُ=An-Nas"
    if "iqro 6" in t: return f"**BAB VIII - IQRO 6, {n}**\n\nTujuan: Baca rangkaian Quran, paham Waqaf, kenal dengung, kenal Nun & Mim Sukun, baca ayat lancar, siap masuk Quran.\n\n**NUN SUKUN (4 hukum):** 1.Izhar Jelas (ء ه ع ح غ خ): مَنْ آمَنَ, عَلِيمٌ حَكِيمٌ 2.Idgham Melebur (ي ر م ل و ن) - Bigunnah (ي ن م و) + dengung: مَنْ يَقُولُ, Bilaghunnah (ل ر) tanpa dengung: مِنْ رَبِّهِمْ 3.Iqlab Jadi Mim samar + dengung (ب): مِنْ بَعْدِ, سَمِيعٌ بَصِيرٌ 4.Ikhfa Samar + dengung (15 huruf ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك): مِنْ قَبْلِ, أَنْفُسَكُمْ\n\n**MIM SUKUN (3 hukum):** 1.Ikhfa Syafawi (ب) samar + dengung: تَرْمِيهِمْ بِحِجَارَةٍ 2.Idgham Mimi (م) lebur + dengung: لَهُمْ مَا 3.Izhar Syafawi (selain م ب) jelas: أَنْعَمْتَ\n\n**QALQALAH** = Pantulan. Huruf 5: ق ط ب ج د (قُطْبُ جَدٍّ). Sugra tengah: يَجْعَلُونَ. Kubra akhir: الْفَلَقْ, أَحَدْ\n\n**GHUNNAH** = Dengung hidung. Huruf م & ن, terutama tasydid. Contoh: إِنَّ, ثُمَّ, النَّاسِ. Dengung 2 harakat.\n\n**WAQAF:** م Harus berhenti, لا Tidak boleh berhenti, ج Boleh berhenti/lanjut, صلى Lebih utama lanjut, قلى Lebih utama berhenti, ۛ ۛ Berhenti di salah satu.\n\nLulus: Bisa baca ayat dengan hukum dasar, panjang pendek, dengung, waqof. SIAP BACA QURAN!"
    if "nun mati" in t: return f"**NUN SUKUN - Iqro 6, {n}**\n\n1.Izhar (ء ه ع ح غ خ) Jelas: مَنْ آمَنَ 2.Idgham Bigunnah (ي ن م و) Lebur+dengung: مَنْ يَقُولُ 3.Idgham Bilaghunnah (ل ر) Lebur tanpa dengung: مِنْ رَبِّهِمْ 4.Iqlab (ب) Jadi Mim: مِنْ بَعْدِ 5.Ikhfa (15 huruf) Samar: مِنْ قَبْلِ"
    if "mim mati" in t: return f"**MIM SUKUN - Iqro 6, {n}**\n\n1.Ikhfa Syafawi (ب) Samar+dengung: تَرْمِيهِمْ بِحِجَارَةٍ 2.Idgham Mimi (م) Lebur+dengung: لَهُمْ مَا 3.Izhar Syafawi (selain م ب) Jelas: أَنْعَمْتَ"
    if "qolqolah" in t or "qalqalah" in t: return f"**QALQALAH - Iqro 6, {n}**\n\nPantulan. Huruf 5: ق ط ب ج د. Sugra tengah: يَجْعَلُونَ. Kubra akhir: أَحَدْ, الْفَلَقْ"
    if "ghunnah" in t or "dengung" in t: return f"**GHUNNAH - Iqro 6, {n}**\n\nDengung hidung. Huruf م & ن, terutama tasydid. Contoh: إِنَّ, ثُمَّ, النَّاسِ. Dengung 2 harakat."
    if "waqof" in t or "waqf" in t: return f"**WAQAF - Iqro 6, {n}**\n\nم Harus berhenti, لا Tidak boleh berhenti, ج Boleh berhenti/lanjut, صلى Lebih utama lanjut, قلى Lebih utama berhenti, ۛ ۛ Berhenti di salah satu."
    if "makhroj iqro" in t or t=="makhroj": return f"**BAB IX - MAKHROJ (Versi Iqro), {n}**\n\nMakhroj = tempat keluar huruf. Tidak cukup kenal huruf, harus ucapkan sesuai tempatnya!\n\n1.Al-Jauf (Rongga): ا و ي. Contoh: قَالَ, يَقُولُ, قِيلَ 2.Al-Halq (Tenggorokan): Bawah ء ه, Tengah ع ح, Atas غ خ 3.Al-Lisan (Lidah): ق ك ج ش ي ض ل ن ر ت د ط ث ذ ظ س ز ص 4.Syafatain (Bibir): ف ب م و 5.Khaisyum (Hidung): Ghunnah. Contoh: إِنَّ, ثُمَّ\n\nLatihan bedain: أ vs ع, ه vs ح, خ vs غ, ك vs ق, س vs ص, ت vs ط, د vs ض, ذ vs ز, ث vs س"
    if "sifat huruf iqro" in t or "sifat huruf" in t: return f"**BAB X - SIFAT HURUF (Versi Iqro), {n}**\n\nSifat = karakter huruf. Bantu bedain huruf yang makhrojnya dekat.\n\nHams vs Jahr - Hams napas mengalir (10 huruf: ف ح ث ه ش خ ص س ك ت), Jahr tertahan.\nSyiddah vs Rakhawah - Syiddah suara tertahan (أ ج د ق ط ب ك ت), Rakhawah mengalir.\nIsti'la vs Istifal - Isti'la pangkal lidah naik tebal (خ ص ض غ ط ق ظ), Istifal tidak naik tipis.\nIthbaq vs Infitah - Ithbaq lidah nempel langit-langit (ص ض ط ظ), Infitah terbuka.\nIdzlaq vs Ishmat - Idzlaq: ف ر م ن ل ب, Ishmat: selain itu."
    if "mad iqro" in t or t=="mad": return f"**BAB XI - MAD (Versi Iqro), {n}**\n\nMad = memanjangkan suara. Panjang pendek harus diperhatikan!\n\n1.Mad Thabi'i 2 harakat: قَالَ, قِيلَ, يَقُولُ 2.Mad Wajib Muttashil 4-5 harakat: جَاءَ, السَّمَاءِ 3.Mad Jaiz Munfashil: يَا أَيُّهَا 4.Mad 'Aridh 2/4/6 harakat: الْعَالَمِينَ 5.Mad Badal: آمَنُوا 6.Mad Lazim 6 harakat: الضَّالِّينَ"
    if "tanda baca" in t: return f"**BAB XII - TANDA BACA, {n}**\n\nَ Fathah=A, ِ Kasrah=I, ُ Dhammah=U, ْ Sukun=Mematikan, ّ Tasydid=Menggandakan, ً Fathatain=AN, ٍ Kasratain=IN, ٌ Dhammatain=UN, ٓ Tanda Mad=Pemanjangan, ٰ Alif Khanjariyah=A panjang"
    if "latihan al-fatihah" in t or ("latihan" in t and "fatihah" in t): return f"**BAB XIII - LATIHAN AL-FATIHAH, {n}**\n\nبِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ / الْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِيْنَ / الرَّحْمٰنِ الرَّحِيْمِ / مٰلِكِ يَوْمِ الدِّيْنِ / إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِيْنُ / اهْدِنَا الصِّرَاطَ الْمُسْتَقِيْمَ / صِرَاطَ الَّذِيْنَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوْبِ عَلَيْهِمْ وَلَا الضَّآلِّيْنَ\n\nFokus: Kenal huruf, harakat, Tasydid, Mad, Ghunnah, Waqaf."
    if "latihan al-ikhlas" in t or ("latihan" in t and "ikhlas" in t): return f"**BAB XIII - LATIHAN AL-IKHLAS, {n}**\n\nقُلْ هُوَ اللّٰهُ أَحَدٌ / اللّٰهُ الصَّمَدُ / لَمْ يَلِدْ وَلَمْ يُولَدْ / وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ\n\nFokus: Qolqolah, Syamsiyah, Mad Thabi'i, Izhar, Idgham, Waqaf."
    if "latihan al-falaq" in t or ("latihan" in t and "falaq" in t): return f"**BAB XIII - LATIHAN AL-FALAQ, {n}**\n\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ / مِنْ شَرِّ مَا خَلَقَ / وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ / وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ / وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ"
    if "metode iqro" in t or "metode" in t: return f"**BAB XIV - METODE MENGAJAR IQRO', {n}**\n\nA.Talaqqi - Guru baca, murid ikuti. Guru tunjuk huruf -> Guru ucap -> Murid dengar -> Murid tiru -> Guru koreksi.\nB.Drill - Baca berulang sampai lancar. Contoh: بَ بِ بُ - تَ تِ تُ\nC.Individual - Tiap anak baca bergantian. Guru tahu kemampuan tiap anak, salah langsung diperbaiki.\nD.Klasikal - Ajar semua bersama. Cocok untuk pengenalan huruf, harakat, baca bersama.\nE.Demonstrasi - Guru contoh langsung cara baca huruf, makhroj, panjang pendek, tajwid."
    if "evaluasi iqro" in t or "evaluasi" in t: return f"**BAB XV - EVALUASI IQRO', {n}**\n\nAspek: 1.Pengenalan huruf 2.Harakat 3.Kelancaran 4.Makhroj 5.Panjang pendek 6.Tajwid dasar\n\nRubrik: 90-100 Sangat Baik (benar & lancar), 80-89 Baik (sedikit salah), 70-79 Cukup (beberapa salah), 60-69 Kurang (banyak salah), <60 Perlu Bimbingan\n\nNaik Jilid Kalau: Kuasai jilid sebelumnya, bisa baca contoh benar, bisa bedain bentuk & bunyi, tidak terlalu bergantung guru, kelancaran memadai. Sesuai standar buku Iqro' & kebijakan TPQ/TPA."
    if "kesalahan iqro" in t or "kesalahan" in t: return f"**BAB XVI - KESALAHAN UMUM IQRO', {n}**\n\n1.س tertukar ص -> Latihan makhroj & sifat 2.ح tertukar ه -> Latihan tenggorokan 3.ك tertukar ق -> Latihan pangkal lidah 4.Panjang dibaca pendek -> Latihan Mad 5.Pendek dipanjangkan -> Latihan harakat 6.Tasydid tidak ditekan -> Latihan Tasydid 7.Tidak perhatikan Sukun -> Latihan menyambung 8.Tidak perhatikan dengung -> Latihan Ghunnah 9.Baca terlalu cepat -> Biasakan Tartil 10.Berhenti kurang tepat -> Latihan Waqaf"
    if "program iqro" in t or "program" in t: return f"**BAB XVII - PROGRAM IQRO' 20 PERTEMUAN, {n}**\n\n1.Pengenalan huruf 2.Fathah 3.Latihan Fathah 4.Huruf bersambung 5.Latihan bersambung 6.Kasrah 7.Dhammah 8.Kombinasi 3 harakat 9.Sukun 10.Mad Thabi'i 11.Tanwin 12.Tasydid 13.Qamariyah & Syamsiyah 14.Nun Sukun & Tanwin 15.Mim Sukun 16.Qolqolah & Ghunnah 17.Waqaf & Mad 18.Praktik Quran 19.Evaluasi 20.Perbaikan bacaan. Ini contoh tematik, bukan pembagian resmi halaman tiap jilid."
    if "soal iqro" in t or "soal" in t: return f"**BAB XVIII - SOAL IQRO', {n}**\n\n1.Jumlah huruf hijaiyah? A.25 B.26 C.28 D.29 -> **D.29** 2.Fathah bunyi? A.A B.I C.U D.An -> **A.A** 3.Kasrah di? A.Atas B.Bawah -> **B.Bawah** 4.Dhammah bunyi? A.A B.I C.U -> **C.U** 5.Sukun? A.Panjang B.Mati -> **B.Mati** 6.Huruf Mad? A.ا و ي -> **A** 7.Tasydid? A.Pendek B.Panjang C.Rangkap -> **C.Rangkap** 8.Qolqolah jumlah? A.3 B.4 C.5 -> **C.5** 9.Idgham Bigunnah? A.يرملون B.ينمو -> **B.ينمو** 10.Mad Thabi'i? A.1 B.2 C.4 -> **B.2 harakat**\n\nPraktik: بَ تَ ثَ جَ حَ خَ / بِ تِ ثِ / بُ تُ ثُ / كَتَبَ, نَصَرَ, يَقُولُ, قَالَ, إِنَّ, الشَّمْسُ, الْقَمَرُ"
    if "kiat iqro" in t or "kiat" in t: return f"**BAB XIX - KIAT IQRO', {n}**\n\n1.Baca Iqro' tiap hari 10-15 menit 2.Ulang materi belum dikuasai 3.Dengarkan contoh guru 4.Praktik di hadapan guru 5.Tidak buru-buru naik jilid 6.Baca suara jelas 7.Rekam bacaan untuk tahu salah 8.Evaluasi berkala 9.Perbanyak praktik Quran 10.Jaga adab belajar Quran"
    if "adab belajar" in t or "adab" in t: return f"**BAB XX - ADAB BELAJAR QURAN, {n}**\n\n1.Niat ikhlas karena Allah 2.Berwudhu saat baca & pegang mushaf 3.Jaga kebersihan tempat belajar 4.Hormati guru 5.Dengarkan contoh guru 6.Tidak bercanda saat belajar 7.Baca tenang tidak tergesa 8.Jaga mushaf & buku Iqro' 9.Amalkan nilai Quran 10.Biasa baca Quran tiap hari\n\nAllah berfirman: وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا - Dan bacalah Al-Quran itu dengan perlahan-lahan. (QS. Al-Muzzammil: 4). Baca tartil: perhatikan pengucapan, panjang pendek, kaidah bacaan.\n\nReferensi: KH. As'ad Humam Buku Iqro' 1-6, Al-Muqaddimah Al-Jazariyyah, Al-Itqan fi Ulum al-Quran, Quran & Terjemahan Kemenag, M. Quraish Shihab Membumikan Al-Quran. Penutup: Yang penting kualitas bacaan, bukan kecepatan selesaikan jilid. Lulus Iqro' 6 tetap perlu bimbingan Tahsin!"
    return f"**Semangat Iqro, {n}! 📖**\n\nKamu nanya: '{t}'\n\nKetik 'Iqro' buat lihat SEMUA BAB I-XX, atau ketik: Iqro 1-6 / Huruf Hijaiyah / Fathah / Tasydid"
# ================= TAHSIN =================
def jawab_tahsin(t,n):
    if t in ["tahsin","materi tahsin","apa itu tahsin","pengertian tahsin"]:
        return f"**MATERI TAHSIN LENGKAP BAB I-XXII, {n}! ✨**\n\nBAB I Pengenalan: Ketik Pengertian tahsin / Bedanya tahsin dan tajwid / Dasar hukum tahsin / Keutamaan baca Quran / Tujuan tahsin\nBAB II Huruf & Harakat: Ketik Huruf Hijaiyah / Harakat\nBAB III Makhroj: Ketik Makhroj\nBAB IV Sifat: Ketik Sifat huruf\nBAB V Nun: Ketik Nun mati\nBAB VI Mim: Ketik Mim mati\nBAB VII Mad: Ketik Mad\nBAB VIII Qolqolah: Ketik Qolqolah\nBAB IX Alif Lam: Ketik Lam Syamsiyah\nBAB X Ra: Ketik Hukum Ra\nBAB XI Lam: Ketik Lam Jalalah\nBAB XII Ghunnah: Ketik Ghunnah\nBAB XIII Waqof: Ketik Waqof\nBAB XIV Tafkhim: Ketik Tafkhim\nBAB XV Kesalahan: Ketik Lahn Jali / Kesalahan pemula\nBAB XVI Metode: Ketik Metode tahsin / Talaqqi\nBAB XVII Tahapan: Ketik Tahapan tahsin\nBAB XVIII Praktik: Ketik Praktik Al-Fatihah\nBAB XIX Evaluasi: Ketik Evaluasi tahsin\nBAB XX Tips: Ketik Tips tahsin\nBAB XXI Istilah: Ketik Istilah tahsin\nBAB XXII Referensi: Ketik Referensi tahsin"
    if "pengertian tahsin" in t or "apa itu tahsin" in t: return f"**BAB I - PENGERTIAN TAHSIN & TAJWID, {n}**\n\nTahsin (تحسين) dari حَسَّنَ - يُحَسِّنُ - تَحْسِينًا = memperbaiki, memperindah. Istilah: Usaha memperbaiki kualitas bacaan Quran agar sesuai kaidah: pengucapan, makhroj, sifat, panjang pendek, tajwid.\n\nTajwid (تَجْوِيْدٌ) bahasa = memperbagus. Istilah: Ilmu cara ucapkan setiap huruf dari makhrajnya dengan hak & sifatnya.\n\nContoh: ق harus dari makhraj benar. ع tidak boleh sama dengan أ. ص tidak boleh dibaca س. Mad harus dipanjangkan sesuai ketentuan."
    if "bedanya tahsin" in t or "perbedaan tahsin" in t: return f"**BAB I - BEDA TAHSIN & TAJWID, {n}**\n\n| Aspek | Tahsin | Tajwid |\n| --- | --- | --- |\n| Pengertian | Memperbaiki kualitas bacaan | Ilmu kaidah membaca |\n| Fokus | Praktik perbaikan | Teori & aturan |\n| Cakupan | Pengucapan, kelancaran, keindahan | Makhroj, sifat, hukum |\n| Tujuan | Bacaan benar & baik | Tahu aturan membaca |\n\nKesimpulan: Tajwid = ilmunya, Tahsin = proses memperbaiki bacaan dengan menerapkan ilmu itu."
    if "dasar hukum" in t or "tartil" in t: return f"**BAB I - DASAR HUKUM TARTIL, {n}**\n\nوَرَتِّلِ الْقُرْآنَ تَرْتِيلًا - Dan bacalah Al-Quran itu dengan perlahan-lahan (tartil). (QS. Al-Muzzammil: 4)\n\nMaksud tartil: Baca tenang, tidak tergesa, perhatikan pengucapan, panjang pendek, tajwid.\n\nAllah juga berfirman: Orang-orang yang telah Kami beri Kitab, mereka membacanya sebagaimana mestinya. (QS. Al-Baqarah: 121)"
    if "keutamaan" in t: return f"**BAB I - KEUTAMAAN BACA QURAN, {n}**\n\nRasulullah: Sebaik-baik kalian adalah orang yang belajar Quran dan mengajarkannya. (HR. Bukhari)\n\nOrang mahir baca Quran akan bersama malaikat mulia, sedangkan yang terbata-bata & kesulitan dapat DUA pahala. (HR. Muslim). Jadi jangan malu kalau masih terbata-bata! Justru dapat 2 pahala: baca + berusaha."
    if "tujuan tahsin" in t: return f"**BAB I - TUJUAN TAHSIN, {n}**\n\n1.Baca Quran benar 2.Paham makhroj 3.Paham sifat 4.Bedain huruf mirip 5.Paham & terapkan tajwid 6.Baca tartil 7.Kurangi kesalahan 8.Tingkatkan kelancaran 9.Tumbuh cinta Quran 10.Biasa baca sesuai kaidah"
    if "huruf hijaiyah" in t or "hijaiyah" in t: return f"**BAB II - HURUF HIJAIYAH, {n}**\n\n1 ا Alif, 2 ب Ba, 3 ت Ta, 4 ث Tsa, 5 ج Jim, 6 ح Ha, 7 خ Kha, 8 د Dal, 9 ذ Dzal, 10 ر Ra, 11 ز Zai, 12 س Sin, 13 ش Syin, 14 ص Shad, 15 ض Dhad, 16 ط Tha, 17 ظ Zha, 18 ع Ain, 19 غ Ghain, 20 ف Fa, 21 ق Qaf, 22 ك Kaf, 23 ل Lam, 24 م Mim, 25 ن Nun, 26 و Wawu, 27 ه Ha, 28 ء Hamzah, 29 ي Ya\n\nCatatan: Alif & Hamzah dibedakan! Alif huruf mad, Hamzah punya makhraj sendiri."
    if "harakat" in t: return f"**BAB II - HARAKAT, {n}**\n\n1.Fathah (َ)=A: بَ=Ba 2.Kasrah (ِ)=I: بِ=Bi 3.Dhammah (ُ)=U: بُ=Bu 4.Fathatain (ً)=AN: بً=Ban 5.Kasratain (ٍ)=IN: بٍ=Bin 6.Dhammatain (ٌ)=UN: بٌ=Bun 7.Sukun (ْ)=Tidak berharakat: أَبْ=Ab 8.Tasydid (ّ)=Rangkap: رَبَّ=Rabba, إِنَّ=Inna"
    if "makhroj" in t or "makhraj" in t: return f"**BAB III - MAKHROJ, {n}**\n\nMakhroj = tempat keluar huruf. Salah makhroj bisa ubah bunyi & makna! 5 tempat utama, 17 makhroj khusus.\n\n**1.AL-JAUF (Rongga mulut & tenggorokan)** - Huruf Mad: ا و ي. Contoh: قَالَ=Qola, يَقُولُ=Yaquulu, قِيلَ=Qiila. Latihan: Ucap panjang, jangan putus sebelum panjangnya.\n\n**2.AL-HALQ (Tenggorokan)** - Bawah: ء ه, Tengah: ع ح, Atas: غ خ. Latihan: أَ - هَ, عَ - حَ, غَ - خَ. Perhatian: ء beda ع, ه beda ح, خ beda غ!\n\n**3.AL-LISAN (Lidah)** - Pangkal belakang: ق, Pangkal depan: ك, Tengah: ج ش ي, Sisi: ض, Ujung sisi: ل, Ujung: ن ر, Ujung+pangkal gigi seri atas: ط د ت, Ujung+ujung gigi seri atas: ظ ذ ث, Ujung dekat gusi bawah: ص س ز. Latihan: قَ - كَ, تَ - طَ, سَ - صَ, دَ - ضَ, ذَ - ظَ\n\n**4.SYAFATAIN (Bibir)** - ف: bibir bawah + ujung gigi seri atas, ب: bibir rapat, م: bibir rapat + dengung, و: bibir bulat tanpa rapat penuh. Latihan: بَ - مَ - وَ - فَ\n\n**5.KHAISYUM (Hidung)** - Ghunnah: Nun Tasydid, Mim Tasydid, Ikhfa, Idgham Bigunnah, Iqlab, Ikhfa Syafawi. Contoh: إِنَّ, ثُمَّ, مِنْ بَعْدِ. Dengung 2 harakat."
    if "sifat" in t: return f"**BAB IV - SIFAT HURUF, {n}**\n\nSifat = karakter bunyi. Makhroj = tempat keluar, Sifat = bagaimana bunyinya.\n\nPunya Lawan: 1.Hams (napas mengalir): فَحَثَّهُ شَخْصٌ سَكَتْ = ف ح ث هـ ش خ ص س ك ت 2.Jahr (napas tertahan): selain Hams 3.Syiddah (suara tertahan): أَجِدْ قَطٍ بَكَتْ = ء ج د ق ط ب ك ت 4.Rakhawah (suara mengalir): selain Syiddah & Tawassuth 5.Tawassuth (pertengahan): لِنْ عُمَرْ = ل ن ع م ر 6.Isti'la (pangkal lidah naik, TEBAL): خُصَّ ضَغْطٍ قِظْ = خ ص ض غ ط ق ظ 7.Istifal (turun, TIPIS): selain Isti'la 8.Ithbaq (lidah nempel langit-langit): ص ض ط ظ 9.Infitah (terbuka): selain Ithbaq 10.Idzlaq (ringan): فَرَّ مِنْ لُبٍّ = ف ر م ن ل ب 11.Ishmat: selain Idzlaq\n\nTanpa Lawan: Shafir (siulan): ص س ز | Qolqolah (pantulan): ق ط ب ج د | Lin (lunak): وْ يْ didahului Fathah | Inhiraf (condong): ل ر | Takrir (getaran): ر - jangan berlebihan! | Tafasysyi (menyebar): ش | Istithalah (memanjang): ض | Ghunnah (dengung): ن م\n\nContoh: س vs ص makhroj dekat, tapi sifat beda!"
    if "nun mati" in t or "nun sukun" in t:
        if "ba" in t: return f"**BAB V - IQLAB, {n}!**\n\nNun ketemu ب. Cara: Nun jadi Mim samar, bibir siap ke Ba, dengung 2 harakat. Contoh: مِنْ بَعْدِ=MIM BA'DI, سَمِيعٌ بَصِيرٌ=SAMII'UM BASHIIR"
        if any(x in t for x in ["ya","waw","wau","mim","nun"]): return f"**BAB V - IDGHAM BIGUNNAH, {n}!**\n\nNun ketemu ي ن م و. Cara: Nun dilebur + dengung 2 harakat. Contoh: مَنْ يَعْمَلْ=MAYYA'MAL, مِنْ نُورٍ=MINNUUR, مِنْ مَالٍ=MIMMAAL. Catatan: Umumnya di 2 kata berbeda."
        if "lam" in t or "ra" in t or "ro" in t: return f"**BAB V - IDGHAM BILAGHUNNAH, {n}!**\n\nNun ketemu ل ر. Cara: Nun dilebur TANPA dengung. Contoh: مِنْ لَدُنْهُ=MILLADUNHU, مِنْ رَبِّهِمْ=MIRROBBIHIM"
        return f"**BAB V - NUN SUKUN & TANWIN, {n}**\n\nNun sukun = Nun tanpa harakat. Contoh: مِنْ, أَنْعَمْتَ. Tanwin = dua harakat bunyinya Nun sukun. Fathatain, Kasratain, Dhammatain. Hukumnya 4:\n\n1.IZHAR HALQI - JELAS. Ketemu ء هـ ع ح غ خ. Cara: Nun jelas tanpa dilebur. Contoh: مَنْ آمَنَ, مِنْ هَادٍ, مِنْ عِلْمٍ, مِنْ حَكِيمٍ, مِنْ غِلٍّ, مِنْ خَيْرٍ\n\n2.IDGHAM - MELEBUR. Huruf: يَرْمَلُونَ. Bigunnah (ي ن م و) lebur + dengung: مَنْ يَعْمَلْ. Bilaghunnah (ل ر) lebur tanpa dengung: مِنْ رَبِّهِمْ\n\n3.IQLAB - JADI MIM SAMAR. Ketemu ب. Cara: Nun jadi Mim samar + dengung 2 harakat. Contoh: مِنْ بَعْدِ, سَمِيعٌ بَصِيرٌ\n\n4.IKHFA HAQIQI - SAMAR. Ketemu 15 huruf: ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك. Cara: Samar antara Izhar & Idgham + dengung 2 harakat. Lidah sesuaikan huruf berikutnya. Contoh: مِنْ تَحْتِهَا, مِنْ شَرِّ, أَنْفُسَكُمْ, مِنْ قَبْلِ"
    if "iqlab" in t: return f"**BAB V - IQLAB, {n}**\n\nNun ketemu ب. Jadi Mim samar + dengung 2 harakat. Contoh: مِنْ بَعْدِ=MIM BA'DI"
    if "izhar" in t: return f"**BAB V - IZHAR HALQI, {n}**\n\nNun ketemu ء هـ ع ح غ خ. Dibaca JELAS. Contoh: مِنْ أَهْلِ=MIN AHLI, مِنْ خَيْرٍ=MIN KHOIR"
    if "ikhfa" in t and "syafawi" not in t: return f"**BAB V - IKHFA HAQIQI, {n}**\n\nNun ketemu 15 huruf: ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك. Dibaca SAMAR + dengung 2 harakat. Contoh: مِنْ تَحْتِهَا, مِنْ شَرِّ, مِنْ قَبْلِ"
    if "mim mati" in t:
        if "ba" in t: return f"**BAB VI - IKHFA SYAFAWI, {n}!**\n\nMim ketemu ب. Contoh: تَرْمِيهِمْ بِحِجَارَةٍ. Cara: Samar + dengung 2 harakat."
        if "mim" in t: return f"**BAB VI - IDGHAM MIMI, {n}!**\n\nMim ketemu م. Disebut juga Idgham Mitslain Shaghir. Contoh: لَهُمْ مَا, كَمْ مِنْ. Cara: Dilebur + dengung 2 harakat."
        return f"**BAB VI - MIM SUKUN, {n}**\n\nMim sukun = Mim tanpa harakat. Contoh: لَهُمْ, أَمْ, عَلَيْهِمْ. Hukumnya 3:\n\n1.IKHFA SYAFAWI - Ketemu ب. Contoh: تَرْمِيهِمْ بِحِجَارَةٍ. Cara: Samar + dengung 2 harakat.\n\n2.IDGHAM MIMI - Ketemu م. Contoh: لَهُمْ مَا, كَمْ مِنْ. Cara: Dilebur + dengung 2 harakat.\n\n3.IZHAR SYAFAWI - Ketemu selain م & ب. Contoh: أَنْعَمْتَ, هُمْ فِيهَا, لَكُمْ دِينُكُمْ. Cara: JELAS. Perhatian: Kalau ketemu ف & و, perjelas Mim karena makhroj dekat bibir!"
    if "mad" in t:
        if "thobi" in t or "thabi" in t or "asli" in t: return f"**BAB VII - MAD THABI'I, {n}**\n\nMad asli, tidak disebabkan Hamzah/Sukun. Panjang 2 harakat. Huruf Mad: Alif setelah Fathah, Waw sukun setelah Dhammah, Ya sukun setelah Kasrah. Contoh: قَالَ, يَقُولُ, قِيلَ"
        if "wajib" in t: return f"**BAB VII - MAD WAJIB MUTTASHIL, {n}**\n\nMad ketemu Hamzah 1 kata. Panjang 4-5 harakat (Hafsh). Contoh: جَاءَ, السَّمَاءِ, سُوءَ"
        if "jaiz" in t or "munfasil" in t: return f"**BAB VII - MAD JAIZ MUNFASHIL, {n}**\n\nMad di akhir kata, Hamzah di awal kata berikutnya. Panjang 4-5 harakat (ada jalur 2 harakat). Contoh: يَا أَيُّهَا, إِنَّا أَنْزَلْنَاهُ"
        if "aridh" in t or "arid" in t: return f"**BAB VII - MAD 'ARIDH LISSUKUN, {n}**\n\nMad sebelum huruf terakhir yang disukun karena Waqof. Panjang 2, 4, atau 6 harakat. Contoh: الْعَالَمِينَ, الرَّحِيمِ, نَسْتَعِينُ"
        if "badal" in t: return f"**BAB VII - MAD BADAL, {n}**\n\nHamzah mendahului huruf Mad 1 kata. Panjang 2 harakat. Contoh: آمَنُوا, إِيمَانًا, أُوتُوا"
        if "iwad" in t: return f"**BAB VII - MAD IWAD, {n}**\n\nBerhenti pada kata berakhir Fathatain (selain Ta Marbuthoh). Tanwin diganti Alif panjang 2 harakat. Contoh: عَلِيمًا -> 'ALIIMAA, حَكِيمًا, غَفُورًا"
        if "lin" in t: return f"**BAB VII - MAD LIN, {n}**\n\nWaw/Ya sukun didahului Fathah + Waqof. Panjang 2, 4, atau 6 harakat. Contoh: خَوْفٍ, بَيْتٍ"
        if "lazim" in t: return f"**BAB VII - MAD LAZIM, {n}**\n\nMad ketemu Sukun asli. Panjang 6 harakat. 4 Jenis: Kilmi Mutsaqqal, Kilmi Mukhaffaf, Harfi Mutsaqqal, Harfi Mukhaffaf. Contoh: الضَّالِّينَ, آلْآنَ, الم"
        if "shilah" in t: return f"**BAB VII - MAD SHILAH, {n}**\n\nHa Dhamir (هُ / هِ) di antara 2 huruf berharakat. Qashirah (tidak ketemu Hamzah): 2 harakat. Contoh: إِنَّهُ كَانَ. Thawilah (ketemu Hamzah): 4-5 harakat. Contoh: مَالَهُ أَخْلَدَهُ"
        return f"**BAB VII - MAD LENGKAP, {n}**\n\nMad = memanjangkan suara huruf Mad/Lin.\n\n| Jenis Mad | Panjang |\n| --- | --- |\n| Mad Thabi'i | 2 harakat |\n| Mad Wajib Muttashil | 4-5 harakat |\n| Mad Jaiz Munfashil | 4-5 harakat |\n| Mad 'Aridh Lissukun | 2, 4, atau 6 harakat |\n| Mad Badal | 2 harakat |\n| Mad Iwad | 2 harakat |\n| Mad Lin | 2, 4, atau 6 harakat |\n| Mad Lazim | 6 harakat |\n| Mad Shilah Qashirah | 2 harakat |\n| Mad Shilah Thawilah | 4-5 harakat |\n\nCatatan: Riwayat Hafsh 'an Ashim, umum di Indonesia. Ketik: Mad Thabi'i / Mad Wajib / Mad Lazim / Mad Shilah"
    if "qolqolah" in t or "qalqalah" in t: return f"**BAB VIII - QALQALAH, {n}**\n\nQalqalah = memantulkan suara huruf Qalqalah dalam keadaan Sukun. Huruf: قُطْبُ جَدٍّ = ق ط ب ج د\n\n1.Qolqolah Sughra - Sukun asli di tengah kata. Pantulan ringan. Contoh: يَجْعَلُونَ, يَقْطَعُونَ, أَبْتَرُ\n\n2.Qolqolah Kubra - Berhenti pada Qolqolah akhir kata. Pantulan lebih kuat. Contoh: أَحَدْ, الْفَلَقْ, الْبُرُوجْ\n\n3.Qolqolah Akbar - Berhenti pada Qolqolah Bertasydid. Pantulan paling kuat. Contoh: الْحَقّ, وَتَبَّ\n\nKesalahan: 1.Memantulkan berlebihan 2.Nambah harakat baru (AHAD jadi AHADE) 3.Baca seperti berharakat 4.Tidak ada pantulan sama sekali"
    if "lam syamsiyah" in t or "lam qomariyah" in t or "alif lam" in t: return f"**BAB IX - ALIF LAM TA'RIF, {n}**\n\nA.QAMARIYAH - Dibaca JELAS. Huruf 14: ا ب ج ح خ ع غ ف ق ك م هـ و ي. Contoh: الْقَمَرُ, الْكِتَابُ, الْحَمْدُ. Cara: Lam dibaca jelas.\n\nB.SYAMSIYAH - TIDAK dibaca. Huruf 14: ت ث د ذ ر ز س ش ص ض ط ظ ل ن. Contoh: الشَّمْسُ, الرَّحْمَٰنُ, النَّاسُ. Cara: Lam tidak dibunyikan, huruf setelahnya bertasydid."
    if "hukum ra" in t or t=="ra": return f"**BAB X - HUKUM RA (ر), {n}**\n\nA.RA TAFKHIM (Tebal): 1.Ra Fathah: رَبِّ 2.Ra Dhammah: رُزِقُوا 3.Ra Sukun didahului Fathah: مَرْيَمَ 4.Ra Sukun didahului Dhammah: قُرْآنٌ\n\nB.RA TARQIQ (Tipis): 1.Ra Kasrah: رِزْقًا 2.Ra Sukun didahului Kasrah asli: فِرْعَوْنَ 3.Kondisi khusus Waqof (lanjutan)\n\nC.BOLEH TEBAL/TIPIS: Ada keadaan tertentu boleh Tafkhim maupun Tarqiq menurut riwayat. Pembahasan lanjutan."
    if "lam jalalah" in t or t=="lam" or "hukum lam" in t: return f"**BAB XI - HUKUM LAM, {n}**\n\nA.LAM JALALAH TAFKHIM (Tebal) - Lam lafaz Allah dibaca tebal kalau didahului Fathah/Dhammah. Contoh: قَالَ اللَّهُ, عَبْدُ اللَّهِ\n\nB.LAM JALALAH TARQIQ (Tipis) - Kalau didahului Kasrah. Contoh: بِسْمِ اللَّهِ, لِلَّهِ\n\nC.LAM SELAIN LAFAZ ALLAH - Umumnya tipis. Contoh: الْحَمْدُ, لَكُمْ"
    if "ghunnah" in t or "dengung" in t: return f"**BAB XII - GHUNNAH, {n}**\n\nGhunnah = dengung dari hidung. Huruf: ن & م\n\nGhunnah Musyaddadah: Nun/Mim Bertasydid. Contoh: إِنَّ, ثُمَّ, أَمَّا, إِنَّمَا. Cara: Dengung 2 harakat.\n\nTingkatan: 1.Nun & Mim Bertasydid 2.Idgham Bigunnah 3.Ikhfa & Iqlab 4.Ikhfa Syafawi 5.Izhar ketika Nun & Mim berharakat/sukun sesuai sifat dasarnya"
    if "waqof" in t or "waqf" in t or "ibtida" in t: return f"**BAB XIII - WAQAF & IBTIDA', {n}**\n\nWaqaf = menghentikan bacaan di akhir kata untuk ambil napas dengan niat lanjut. Ibtida' = memulai kembali setelah berhenti. Penting karena berkaitan dengan kesempurnaan makna.\n\nTanda: م (Lazim) Harus berhenti, لا (La Waqfa) Tidak dianjurkan berhenti, ج (Jaiz) Boleh berhenti/lanjut, صلى (Washal Aula) Lebih utama lanjut, قلى (Waqaf Aula) Lebih utama berhenti, ∴ ∴ (Mu'anaqah) Berhenti di salah satu bukan keduanya, ط (Muthlaq) Dianjurkan berhenti, ز (Mujawwaz) Boleh berhenti, lanjut lebih utama. Catatan: Tanda bisa beda di mushaf lain.\n\nMacam Berdasarkan Makna: 1.Waqaf Tam - Makna sempurna, tidak ada kaitan kuat dengan berikutnya 2.Waqaf Kafi - Makna dipahami, masih ada hubungan makna 3.Waqaf Hasan - Makna dipahami, hubungan kuat dengan sesudahnya 4.Waqaf Qabih - Makna tidak sempurna/berubah. Jangan dilakukan!"
    if "tafkhim" in t or "tarqiq" in t: return f"**BAB XIV - TAFKHIM & TARQIQ, {n}**\n\nTafkhim = baca TEBAL. Huruf Isti'la: خ ص ض غ ط ق ظ. Contoh: خَالِدِينَ, صِرَاطَ, طَيِّبًا, قَالَ\n\nTarqiq = baca TIPIS. Sebagian besar huruf tipis, kecuali huruf Tafkhim. Ada huruf khusus seperti Ra & Lam Jalalah.\n\nLatihan: سَ - صَ, تَ - طَ, دَ - ضَ, ذَ - ظَ"
    if "lahn jali" in t or "lahn khafi" in t or "lahn" in t or "kesalahan pemula" in t: return f"**BAB XV - KESALAHAN (LAHN), {n}**\n\nA.LAHN JALI - Kesalahan JELAS. Perubahan huruf, harakat, susunan. Bisa ubah makna! Contoh: 1.ح jadi ه 2.ع jadi أ 3.ص jadi س 4.Fathah jadi Kasrah 5.Hilang Tasydid 6.Nambah huruf 7.Hilang huruf. Harus segera diperbaiki!\n\nB.LAHN KHAFI - Kesalahan TERSEMBUNYI. Hanya diketahui yang paham tajwid. Contoh: 1.Mad tidak sesuai 2.Dengung kurang tepat 3.Qolqolah terlalu lemah/berlebihan 4.Tafkhim & Tarqiq tidak tepat 5.Pengucapan kurang sempurna 6.Ikhfa kurang tepat 7.Waqaf & Ibtida' tidak tepat\n\nKesalahan Pemula: ع dibaca أ -> Harusnya makhroj tengah tenggorokan | ح dibaca ه -> Harusnya tenggorokan tengah | ص dibaca س -> Harusnya Isti'la & Ithbaq | ق dibaca ك -> Harusnya pangkal lidah lebih belakang | ث dibaca س -> Harusnya ujung lidah di antara gigi | ذ dibaca ز -> Harusnya ujung lidah di antara gigi | ض dibaca د -> Harusnya sisi lidah | Mad terlalu pendek -> Perhatikan harakat | Dengung tidak jelas -> Latih Ghunnah dari hidung"
    if "metode tahsin" in t or "talaqqi" in t or "musyafahah" in t: return f"**BAB XVI - METODE TAHSIN, {n}**\n\nA.Talaqqi - Baca langsung di hadapan guru. Guru contoh -> Murid dengar -> Murid tiru -> Guru koreksi -> Murid ulang sampai benar.\n\nB.Musyafahah - Perhatikan gerakan mulut guru. Penting untuk huruf sulit: ع, ح, ض, ظ, ق.\n\nC.Drill - Ulang pengucapan sampai benar. Contoh: صَ - صِ - صُ, سَ - سِ - سُ, قَ - قِ - قُ\n\nD.Tikrar - Pengulangan bacaan. 1 ayat dibaca 3-5x dengan koreksi guru.\n\nE.Setoran Bacaan - Baca individual di hadapan guru. Dinilai: Makhroj, Sifat, Tajwid, Kelancaran, Waqaf & Ibtida'."
    if "tahapan tahsin" in t or "tahapan" in t: return f"**BAB XVII - TAHAPAN 16 PERTEMUAN, {n}**\n\n1.Pengenalan tahsin & keutamaan 2.Huruf & harakat 3.Makhroj Jauf & Halq 4.Makhroj Lisan 5.Makhroj Syafatain & Khaisyum 6.Sifat huruf 7.Nun sukun & tanwin 8.Mim sukun & Ghunnah 9.Mad Thabi'i & Mad Far'i 10.Qolqolah 11.Alif Lam 12.Ra & Lam Jalalah 13.Waqaf & Ibtida' 14.Praktik Al-Fatihah 15.Praktik Juz Amma 16.Evaluasi akhir"
    if "praktik al-fatihah" in t or "praktik" in t: return f"**BAB XVIII - PRAKTIK AL-FATIHAH, {n}**\n\nAl-Fatihah wajib diperbaiki karena dibaca tiap rokaat!\n\n| Ayat | Aspek Tahsin |\n| --- | --- |\n| بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ | Lam Jalalah, Ra Tafkhim, Mad Thabi'i |\n| الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ | Lam Jalalah Tarqiq, Tasydid, Mad |\n| الرَّحْمَٰنِ الرَّحِيمِ | Ra Tafkhim, Ra Tarqiq, Mad |\n| مَالِكِ يَوْمِ الدِّينِ | Mad Thabi'i, Ya Lin, Tasydid |\n| إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ | Mad, Tasydid, Ghunnah, Mad 'Aridh |\n| اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ | Hamzah Washal, Shad, Ra Tafkhim, Qolqolah |\n| صِرَاطَ الَّذِينَ أَنْعَمْتَ... الضَّالِّينَ | Tafkhim, Tarqiq, Izhar, Mad Lazim |\n\nSurah latihan lain: Al-Ikhlas, Al-Falaq, An-Nas, Al-Kautsar, Al-'Ashr, Al-Ma'un, Al-Kafirun, An-Nashr, Al-Lahab."
    if "evaluasi tahsin" in t or "evaluasi" in t: return f"**BAB XIX - EVALUASI TAHSIN, {n}**\n\n5 Aspek: 1.Makhroj 2.Sifat 3.Tajwid 4.Panjang Pendek 5.Kelancaran & Tartil\n\nRubrik: Makhroj 25, Sifat 20, Tajwid 25, Panjang Pendek 15, Kelancaran 15. Total 100.\n\nKategori: 90-100 Sangat Baik, 80-89 Baik, 70-79 Cukup, 60-69 Kurang, <60 Perlu Bimbingan\n\nContoh Soal: 1.Apa itu Tahsin? Usaha memperbaiki bacaan sesuai Makhroj, Sifat, Tajwid. 2.Beda Tahsin & Tajwid? Tajwid ilmunya, Tahsin prosesnya. 3.Berapa tempat utama Makhroj? 5 tempat. 4.Sebutkan 5 tempat! Jauf, Halq, Lisan, Syafatain, Khaisyum. 5.Apa itu Ikhfa Haqiqi? Nun samar ketemu 15 huruf + dengung. 6.Huruf Qolqolah? ق ط ب ج د. 7.Beda Tafkhim & Tarqiq? Tebal vs Tipis. 8.Panjang Mad Thabi'i? 2 harakat. 9.Apa itu Ghunnah? Dengung dari hidung. 10.Apa itu Waqaf? Berhenti untuk ambil napas dengan niat lanjut.\n\nPraktik Ujian: Baca Al-Fatihah, Al-Ikhlas, Al-Falaq, An-Nas di hadapan guru."
    if "tips tahsin" in t or "tips" in t: return f"**BAB XX - TIPS TAHSIN, {n}**\n\n1.Belajar Langsung ke Guru - Buku/video tidak cukup, harus dikoreksi guru. 2.Mulai dari Makhroj - Jangan buru-buru Tajwid rumit kalau huruf dasar belum benar. 3.Latihan Tiap Hari - 15-30 menit tiap hari. 4.Talaqqi - Dengar guru, perhatikan mulutnya, tirukan. 5.Rekam Bacaan - Rekam, dengerin salahnya. Koreksi akhir tetap oleh guru. 6.Tidak Terburu-buru - Tujuan bukan banyak halaman, tapi kualitas. 7.Ulang Materi Belum Dikuasai - Kalau masih susah bedain س & ص, latihan khusus sampai benar!"
    if "istilah tahsin" in t or "istilah" in t: return f"**BAB XXI - ISTILAH TAHSIN, {n}**\n\nTahsin: Memperbaiki bacaan | Tajwid: Ilmu kaidah membaca | Tartil: Baca perlahan & teratur | Makhroj: Tempat keluar huruf | Sifat: Karakteristik huruf | Ghunnah: Dengung | Mad: Memanjangkan suara | Qolqolah: Memantulkan suara | Tafkhim: Baca tebal | Tarqiq: Baca tipis | Idgham: Meleburkan huruf | Izhar: Baca jelas | Ikhfa: Baca samar | Iqlab: Nun jadi Mim samar | Waqaf: Menghentikan bacaan | Ibtida': Memulai bacaan | Lahn Jali: Kesalahan jelas | Lahn Khafi: Kesalahan tersembunyi | Talaqqi: Belajar langsung ke guru | Musyafahah: Belajar perhatikan gerakan mulut guru"
    if "referensi tahsin" in t or "referensi" in t: return f"**BAB XXII - REFERENSI TAHSIN, {n}**\n\nKitab Klasik: 1.Hidayatul Mustafid fi Ahkamit Tajwid - Dasar Tajwid 2.Tuhfatul Athfal - Syaikh Sulaiman al-Jamzuri - Nun sukun, Mim sukun, Ghunnah, Mad 3.Al-Muqaddimah Al-Jazariyyah - Imam Al-Jazari - Makhroj & Sifat 4.Ghayatul Murid fi 'Ilmit Tajwid - 'Athiyyah Qabil Nashr\n\nAl-Quran: 1.Quran & Terjemahan Kemenag RI 2.Mushaf Standar Indonesia 3.Mushaf riwayat Hafsh 'an Ashim\n\nPrinsip: Kenal Huruf -> Perbaiki Makhroj -> Pahami Sifat -> Pelajari Tajwid -> Praktik Baca -> Evaluasi & Perbaiki."
    return f"**Semangat Tahsin, {n}! ✨**\n\nKamu nanya: '{t}'\n\nKetik 'Tahsin' buat lihat SEMUA BAB I-XXII, atau ketik: Pengertian tahsin / Makhroj / Nun mati / Mad / Qolqolah / Waqof"
# ================= TAHFIDZ =================
def jawab_tahfidz(t,n):
    if t in ["tahfidz","materi tahfidz","apa itu tahfidz","pengertian tahfidz"]:
        return f"**MATERI TAHFIDZ LENGKAP BAB I-XVII, {n}! 🤲**\n\nBAB I Pengenalan: Ketik Pengertian tahfidz / Tujuan tahfidz / Dasar hukum tahfidz\nBAB II Persiapan: Ketik Persiapan menghafal / Niat / Waktu menghafal\nBAB III Adab: Ketik Adab menghafal\nBAB IV Metode: Ketik Metode Wahdah / Kitabah / Sima'i / Talaqqi / Tasmi' / Jama'\nBAB V Teknik: Ketik Teknik hafal / Murottal\nBAB VI Surah: Ketik Surah pendek / Tahap pemula\nBAB VII Murojaah: Ketik Murojaah\nBAB VIII Target: Ketik Target hafalan\nBAB IX Kesalahan: Ketik Kesalahan menghafal\nBAB X Guru: Ketik Peran guru\nBAB XI Evaluasi: Ketik Evaluasi tahfidz\nBAB XII Usia: Ketik Strategi usia\nBAB XIII Program: Ketik Program 30 hari\nBAB XIV Motivasi: Ketik Motivasi / Doa\nBAB XV Soal: Ketik Soal tahfidz\nBAB XVI Indikator: Ketik Indikator tahfidz\nBAB XVII Kesimpulan: Ketik Kesimpulan tahfidz"
    if "pengertian tahfidz" in t or "apa itu tahfidz" in t: return f"**BAB I - PENGERTIAN TAHFIDZ, {n}**\n\nBahasa: حَفَّظَ - يُحَفِّظُ - تَحْفِيظًا = menjaga, memelihara, menghafalkan. Istilah: Menghafalkan ayat Quran dengan cara membaca, mengulang, mengingat, dan menjaga hafalan agar tetap melekat dan bisa dibacakan kembali dengan benar sesuai tajwid.\n\nSebutan: Hafizh (laki-laki), Hafizhah (perempuan), Huffazh (jamak).\n\nTahapan: 1.Baca ayat 2.Perbaiki makhroj 3.Terapkan tajwid 4.Ulang berulang 5.Hafal bertahap 6.Setor ke guru 7.Ulang hafalan 8.Jaga kualitas jangka panjang. Tahfidz bukan cuma hafal huruf, tapi membangun kedekatan dengan Quran."
    if "tujuan tahfidz" in t: return f"**BAB I - TUJUAN TAHFIDZ, {n}**\n\nUmum: Membentuk generasi Muslim yang mampu menghafal, membaca, menjaga, memahami, dan mengamalkan Quran.\n\nKhusus: 1.Kenal konsep tahfidz 2.Baca Quran baik & benar 3.Hafal bertahap 4.Ingat kembali hafalan 5.Terapkan tajwid 6.Setor ke guru 7.Murojaah mandiri 8.Tumbuh cinta Quran 9.Biasa baca & hafal tiap hari 10.Amalkan nilai Quran"
    if "dasar hukum tahfidz" in t or "dasar hukum" in t: return f"**BAB I - DASAR HUKUM TAHFIDZ, {n}**\n\nA.QS. Al-Hijr: 9 - إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ - Sesungguhnya Kamilah yang menurunkan Al-Quran dan Kami benar-benar memeliharanya. Allah jamin pemeliharaan Quran lewat membaca, mempelajari, menghafalkan, mengamalkannya.\n\nB.HR. Bukhari - خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ - Sebaik-baik kalian adalah orang yang belajar Quran dan mengajarkannya."
    if "persiapan menghafal" in t or "persiapan" in t: return f"**BAB II - PERSIAPAN MENGHAFAL, {n}**\n\n1.Niat - Ketik: Niat 2.Kemauan Kuat - Sabar, tekun, konsisten. Hafal tiap hari, tidak mudah menyerah, ulang teratur, perbaiki kesalahan, tidak buru-buru kejar jumlah. 3.Perbaiki Bacaan Dulu - Kuasai: huruf, harakat, makhroj, sifat, nun sukun, mim sukun, mad, waqof, tajwid. Prinsip: Lebih baik hafal sedikit tapi benar, daripada banyak tapi salah! 4.Mushaf yang Sama - Pakai mushaf sama terus. Biar ingat posisi ayat, letak halaman, gambaran visual. 5.Waktu Menghafal - Ketik: Waktu menghafal"
    if "niat" in t: return f"**BAB II - NIAT, {n}**\n\nNiat menghafal yang benar: Mendekatkan diri kepada Allah, mengharap ridha Allah, menjaga kemurnian Quran, meningkatkan kualitas ibadah, mengamalkan isi Quran. Jangan hanya bertujuan dapat penghargaan, nilai, atau pujian manusia."
    if "waktu menghafal" in t or t=="waktu": return f"**BAB II - WAKTU MENGHAFAL, {n}**\n\nSetelah Subuh: Hafalan baru. Pagi: Ulang hafalan. Setelah Zuhur: Perbaiki hafalan. Setelah Asar: Murojaah. Setelah Magrib: Setor hafalan. Sebelum tidur: Ulang hafalan ringan. Ini rekomendasi, bukan ketentuan mutlak!"
    if "adab menghafal" in t or "adab tahfidz" in t or t=="adab": return f"**BAB III - ADAB MENGHAFAL, {n}**\n\nKepada Allah: Luruskan niat, ikhlas, mohon pertolongan Allah, jaga ibadah wajib, hindari maksiat, berdoa sebelum & sesudah belajar.\n\nTerhadap Quran: Jaga kebersihan mushaf, perlakukan dengan hormat, baca tartil, tidak main-main, perhatikan kesucian, jaga hafalan dengan murojaah, amalkan ajarannya.\n\nTerhadap Guru: Hormati guru, dengarkan arahan, tidak memotong pembicaraan, perhatikan contoh guru, terima koreksi lapang dada, tidak malu bertanya.\n\nTerhadap Sesama: Tidak merendahkan hafalan orang lain, tidak membandingkan berlebihan, saling bantu, saling simak, beri motivasi, hargai proses masing-masing."
    if "wahdah" in t: return f"**BAB IV - METODE WAHDAH, {n}**\n\nWahdah = hafal ayat demi ayat berulang-ulang. Langkah: 1.Guru tentukan ayat 2.Baca ayat pertama 3.Ulang 10-20x 4.Coba hafal tanpa mushaf 5.Kalau lancar lanjut ayat berikutnya 6.Gabung ayat 1+2 7.Ulang sampai lancar. Contoh Al-Ikhlas ayat 1: قُلْ هُوَ اللّٰهُ أَحَدٌ - Baca berulang sampai bisa tanpa lihat mushaf!"
    if "kitabah" in t: return f"**BAB IV - METODE KITABAH, {n}**\n\nKitabah = hafal dengan MENULIS ayat. Langkah: 1.Baca ayat 2.Perhatikan tulisannya 3.Tulis di buku 4.Baca lagi tulisanmu 5.Hafalkan 6.Tutup tulisan, coba tulis lagi 7.Cek dengan mushaf. Cocok buat tipe visual & kinestetik!"
    if "sima" in t: return f"**BAB IV - METODE SIMA'I, {n}**\n\nSima'i = hafal dengan MENDENGARKAN. Langkah: 1.Guru/murottal perdengarkan ayat 2.Dengarkan saksama 3.Perhatikan makhroj & tajwid 4.Ikuti bacaan guru 5.Ulang beberapa kali 6.Coba hafal tanpa audio. Cocok untuk anak-anak yang butuh contoh langsung."
    if "talaqqi" in t: return f"**BAB IV - METODE TALAQQI, {n}**\n\nTalaqqi = guru baca, murid tiru. Langkah: 1.Guru bacakan ayat benar 2.Murid dengar 3.Murid tiru 4.Guru perbaiki salah 5.Murid ulang sampai benar 6.Murid hafal 7.Guru simak. Kelebihan: Guru langsung perbaiki makhroj, sifat, tajwid!"
    if "tasmi" in t: return f"**BAB IV - METODE TASMI', {n}**\n\nTasmi' = memperdengarkan hafalan ke guru/orang lain. Langkah: 1.Siapkan hafalan 2.Guru tentukan bagian 3.Baca tanpa mushaf 4.Guru perhatikan kelancaran & ketepatan 5.Guru koreksi 6.Perbaiki. Beda Tasmi' vs Murojaah: Tasmi' = setor untuk diuji. Murojaah = ulang sendiri untuk jaga hafalan."
    if "metode jama" in t or t=="jama": return f"**BAB IV - METODE JAMA', {n}**\n\nJama' = hafal bersama-sama. Langkah: 1.Guru bacakan ayat 2.Semua dengar 3.Guru+murid baca bersama 4.Ulang beberapa kali 5.Baca bersama tanpa mushaf 6.Guru tunjuk beberapa murid hafal individu."
    if "metode gabungan" in t or "metode hafal" in t or "metode menghafal" in t or "cara hafal" in t or "cara menghafal" in t: return f"**BAB IV - METODE LENGKAP, {n}**\n\n1.Wahdah - Ayat demi ayat 10-20x. Ketik: Wahdah 2.Kitabah - Menulis ayat. Ketik: Kitabah 3.Sima'i - Mendengarkan. Ketik: Sima'i 4.Talaqqi - Guru baca, murid tiru. Ketik: Talaqqi 5.Tasmi' - Setor ke guru. Ketik: Tasmi' 6.Murajaah - Ulang hafalan. Ketik: Murojaah 7.Jama' - Hafal bersama. Ketik: Jama' 8.Gabungan - Gabung semua! Talaqqi perbaiki bacaan + Sima'i ingat ayat + Wahdah hafal + Kitabah kuatkan ingatan + Tasmi' uji + Murojaah jaga. Paling bagus karena tiap anak beda cara belajar!"
    if "teknik hafal" in t or "teknik" in t: return f"**BAB V - TEKNIK PRAKTIS, {n}**\n\n1.Ayat demi Ayat: Contoh Al-Falaq: Hafal ayat 1, hafal ayat 2, gabung 1+2, lanjut ayat 3, gabung semua.\n2.Pengulangan: 1-5x lihat mushaf, 6-10x perhatikan pelafalan, 11-15x lebih lancar, 16-20x coba tanpa lihat, lanjut sampai lancar. Jumlah bukan patokan baku!\n3.Murottal: Pilih qari bagus, dengar 1 ayat berulang, perhatikan panjang pendek, ikuti qari, ulang tanpa audio, cek mushaf.\n4.Bagi Ayat: Ayat panjang dibagi potongan pendek sesuai tempat berhenti. Hafal per potong, baru gabung.\n5.Pahami Arti: Al-Ikhlas ayat 1: Qul Huwallaahu Ahad = Katakanlah, Dialah Allah Yang Maha Esa. Paham arti = gampang ingat urutan.\n6.Dalam Sholat: Pakai hafalan di sholat. Kuatkan hafalan, biasakan pakai, hubungkan dengan ibadah, latih ingat tanpa mushaf."
    if "murottal" in t: return f"**BAB V - MUROTTAL, {n}**\n\nMurottal = bacaan Quran tartil. Cara: Pilih qari bagus, dengar 1 ayat berulang, perhatikan panjang pendek, ikuti qari, ulang tanpa audio, cek mushaf."
    if "surah pendek" in t or "tahap pemula" in t or "tahap menengah" in t or "tahap lanjutan" in t or "juz 30" in t: return f"**BAB VI - SURAH PENDEK, {n}**\n\nPEMULA - Fokus: Hafal ayat pendek, perbaiki pelafalan, paham urutan, biasakan murojaah: Al-Fatihah, Al-Ikhlas, Al-Falaq, An-Nas, Al-Lahab, An-Nashr, Al-Kafirun, Al-Kautsar, Al-Ma'un, Quraisy.\n\nMENENGAH - Fokus: Ayat lebih panjang, jaga urutan, terapkan tajwid, setor mandiri: Al-Fil, Al-Humazah, Al-'Ashr, At-Takatsur, Al-Qari'ah, Al-'Adiyat, Az-Zalzalah, Al-Bayyinah, Al-Qadr, Al-'Alaq.\n\nLANJUTAN - Fokus: Ayat lebih panjang, hubungkan ayat, jaga ketepatan, tingkatkan tasmi': At-Tin, Asy-Syarh, Ad-Dhuha, Al-Lail, Asy-Syams, Al-Balad, Al-Fajr, Al-Ghasyiyah, Al-A'la, Ath-Thariq.\n\nKetik nama surahnya! Contoh: Al-Fatihah"
    if "al-fatihah" in t or "fatihah" in t: return f"**Al-Fatihah (7 ayat), {n}**\n\n1. بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\n2. الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ\n3. الرَّحْمَٰنِ الرَّحِيمِ\n4. مَالِكِ يَوْمِ الدِّينِ\n5. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ\n6. اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ\n7. صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ\n\nCara Wahdah: Hafal 1-2 dulu, lancar baru 3-4, baru 5-7!"
    if "al-ikhlas" in t or "ikhlas" in t: return f"**Al-Ikhlas (4 ayat), {n}**\n\n1. قُلْ هُوَ اللَّهُ أَحَدٌ\n2. اللَّهُ الصَّمَدُ\n3. لَمْ يَلِدْ وَلَمْ يُولَدْ\n4. وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ\n\nArtinya: Katakanlah, Dialah Allah Yang Maha Esa."
    if "an-nas" in t or "an nas" in t: return f"**An-Nas (6 ayat), {n}**\n\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ - مَلِكِ النَّاسِ - إِلَٰهِ النَّاسِ - مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ - الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ - مِنَ الْجِنَّةِ وَالنَّاسِ"
    if "al-falaq" in t or "falaq" in t: return f"**Al-Falaq (5 ayat), {n}**\n\n1. قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ\n2. مِنْ شَرِّ مَا خَلَقَ\n3. وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ\n4. وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ\n5. وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ"
    if "al-kautsar" in t or "kautsar" in t: return f"**Al-Kautsar (3 ayat), {n}**\n\n1. إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ\n2. فَصَلِّ لِرَبِّكَ وَانْحَرْ\n3. إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ"
    if "al-ashr" in t or "ashr" in t: return f"**Al-Ashr (3 ayat), {n}**\n\n1. وَالْعَصْرِ\n2. إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ\n3. إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ"
    if "an-nashr" in t or "nashr" in t: return f"**An-Nashr (3 ayat), {n}**\n\n1. إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ\n2. وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا\n3. فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ ۚ إِنَّهُ كَانَ تَوَّابًا"
    if "al-lahab" in t or "lahab" in t: return f"**Al-Lahab (5 ayat), {n}**\n\n1. تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ\n2. مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ\n3. سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ\n4. وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ\n5. فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ"
    if "al-kafirun" in t or "kafirun" in t: return f"**Al-Kafirun (6 ayat), {n}**\n\n1. قُلْ يَا أَيُّهَا الْكَافِرُونَ\n2. لَا أَعْبُدُ مَا تَعْبُدُونَ\n3. وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ\n4. وَلَا أَنَا عَابِدٌ مَا عَبَدْتُمْ\n5. وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ\n6. لَكُمْ دِينُكُمْ وَلِيَ دِينِ"
    if "murojaah" in t or "murajaah" in t: return f"**BAB VII - MUROJAAH, {n}**\n\nPengertian: Dari رَاجَعَ = mengulang kembali / memeriksa kembali. Mengulang hafalan untuk pertahankan kelancaran & ketepatan.\n\nTujuan: Kuatkan hafalan, kurangi kesalahan, pertahankan urutan, latih daya ingat, tahu bagian lemah, jaga jangka panjang.\n\nJenis: Mandiri (sendiri), Bersama (kelompok), Dengan Guru, Dengan Teman (saling simak), Melalui Sholat.\n\nSistem: Harian (tiap hari), Mingguan (semua hafalan seminggu), Bulanan (evaluasi sebulan), Sebelum nambah hafalan (pastikan lama kuat), Acak (guru pilih ayat acak).\n\nContoh 5 Surah: Senin Surah 1, Selasa Surah 2, Rabu Surah 3, Kamis Surah 4, Jumat Surah 5, Sabtu Semua, Ahad Evaluasi.\n\nPrinsip: Konsisten, jangan cuma fokus baru, dahulukan perbaiki yang lemah, jangan buru-buru nambah target, setor ke guru, evaluasi berkala.\n\nIngat: Sukses tahfidz bukan cuma banyak ayat, tapi kemampuan MENJAGA hafalan!"
    if "target hafalan" in t or "target" in t: return f"**BAB VIII - TARGET HAFALAN, {n}**\n\nHarian: Pemula 1-3 ayat pendek, Menengah 3-5 ayat, Lanjutan 5-10 ayat / sesuai kemampuan. Fleksibel!\n\nMingguan: Senin-Kamis Hafalan baru, Jumat Murojaah, Sabtu Tasmi', Ahad Evaluasi mandiri.\n\nBulanan (Pemula): Minggu 1 Al-Ikhlas & Al-Falaq, Minggu 2 An-Nas & Al-Lahab, Minggu 3 An-Nashr & Al-Kafirun, Minggu 4 Al-Kautsar & Al-Ma'un. Ini contoh, bukan wajib!"
    if "kesalahan menghafal" in t or "kesalahan" in t or "lupa" in t: return f"**BAB IX - KESALAHAN UMUM, {n}**\n\n1.Hafal tanpa perbaiki bacaan - Fokus ingat tapi abaikan makhroj & tajwid. Solusi: Talaqqi dulu! 2.Terlalu cepat nambah hafalan - Kejar jumlah tanpa kualitas. Solusi: Pastikan lama kuat dulu! 3.Jarang murojaah - Cuma hafal baru. Solusi: Waktu khusus murojaah tiap hari! 4.Tidak konsisten - Hafal cuma pas belajar. Solusi: Rutin di rumah! 5.Tidak perhatikan sambungan ayat - Bisa per ayat tapi susah gabung. Solusi: Latih bersambung awal-akhir surah! 6.Kurang percaya diri - Takut setor. Solusi: Guru ciptakan suasana nyaman, motivasi, jangan mempermalukan!"
    if "peran guru" in t or "guru" in t: return f"**BAB X - PERAN GURU, {n}**\n\n1.Pembimbing - Bimbing baca & hafal 2.Motivator - Dorong semangat 3.Korektor - Perbaiki salah 4.Evaluator - Nilai perkembangan 5.Teladan - Contoh baca, hafal, adab 6.Pengelola - Atur jadwal, target, kelompok, murojaah, tasmi', evaluasi."
    if "evaluasi tahfidz" in t or "evaluasi" in t: return f"**BAB XI - EVALUASI TAHFIDZ, {n}**\n\n5 Aspek: 1.Kelancaran (tanpa banyak berhenti) 2.Ketepatan (susunan & lafaz tepat) 3.Tajwid (hukum tepat) 4.Makhroj (pengucapan tepat) 5.Adab (kesungguhan & sikap).\n\nRubrik: 90-100 Sangat Baik, 80-89 Baik, 70-79 Cukup, 60-69 Kurang, <60 Perlu Bimbingan.\n\nBentuk: Harian (uji baru), Mingguan (uji seminggu), Bulanan (uji sebulan), Akhir Program (setor semua).\n\nContoh Buku Kontrol: Senin Al-Ikhlas 1-4 Baik/Baik, Selasa Al-Falaq 1-5 Baik/Baik, Rabu An-Nas 1-6 Cukup/Baik, Kamis Al-Lahab 1-5 Baik/Cukup, Jumat Murojaah Semua -/Baik."
    if "strategi usia" in t or "strategi" in t: return f"**BAB XII - STRATEGI BERDASARKAN USIA, {n}**\n\nAnak Usia Dini: Butuh menyenangkan, suka suara & gambar, butuh pengulangan, pendampingan intensif. Strategi: Sima'i, Talaqqi, surah pendek, permainan edukatif, penghargaan sederhana.\n\nSD: Mulai hafal mandiri, bisa ikut jadwal, paham makna sederhana. Strategi: Wahdah, Jama', target harian, murojaah kelompok, evaluasi mingguan.\n\nSMP/MTs: Kemampuan lebih berkembang, bisa atur target, butuh motivasi & pengawasan. Strategi: Gabungan, hafalan mandiri, tasmi', buku kontrol, evaluasi bulanan.\n\nSMA/MA & Dewasa (Kamu!): Bisa kelola target mandiri, paham makna lebih dalam, butuh manajemen waktu. Strategi: Target jangka panjang, Wahdah & Murojaah, halaqah, tasmi' berkala, gabung hafalan + tafsir sederhana."
    if "program 30 hari" in t or "program" in t: return f"**BAB XIII - PROGRAM 30 HARI (Pemula), {n}**\n\n1 Pengenalan Tahfidz, 2 Adab, 3 Perbaiki bacaan, 4-5 Al-Ikhlas 1-2 lalu 3-4, 6 Murojaah Al-Ikhlas, 7 Setoran Al-Ikhlas, 8-9 Al-Falaq 1-2 lalu 3-5, 10 Murojaah Al-Falaq, 11-13 An-Nas 1-2, 3-4, 5-6, 14 Setoran, 15-16 Al-Lahab 1-2 lalu 3-5, 17 Murojaah Al-Lahab, 18-19 An-Nashr 1-2 lalu 3, 20 Murojaah An-Nashr, 21 Setoran, 22-23 Al-Kafirun 1-3 lalu 4-6, 24 Murojaah Al-Kafirun, 25 Al-Kautsar 1-3, 26 Murojaah Al-Kautsar, 27 Murojaah semua, 28 Tasmi', 29 Evaluasi acak, 30 Penilaian akhir. Sesuaikan dengan kemampuan awal!"
    if "motivasi" in t: return f"**BAB XIV - MOTIVASI, {n}**\n\n1.Jangan malu hafalan masih sedikit 2.Jangan bandingkan dengan orang lain 3.Jangan menyerah saat sulit 4.Biasakan hafal tiap hari 5.Jangan lupakan hafalan lama 6.Nikmati proses 7.Jadikan Quran bagian hidup.\n\nIngat: Semua penghafal pernah lupa. Yang sukses itu yang MAU ngulang lagi!"
    if "doa" in t: return f"**BAB XIV - DOA PENGHAFAL, {n}**\n\nDoa Kemudahan: رَبِّ زِدْنِي عِلْمًا - Ya Tuhanku, tambahkanlah ilmu kepadaku. (QS. Thaha: 114)\n\nDoa Ilmu Bermanfaat: اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا - Ya Allah, aku mohon ilmu bermanfaat, rezeki baik, dan amal yang diterima. (Doa setelah Subuh)"
    if "soal tahfidz" in t or "soal" in t: return f"**BAB XV - SOAL & LATIHAN, {n}**\n\nSoal Pengetahuan: 1.Apa itu tahfidz? 2.Apa tujuan utama hafal Quran? 3.Apa itu Wahdah? 4.Jelaskan Talaqqi! 5.Beda Tasmi' & Murojaah? 6.Kenapa tajwid penting sebelum hafal? 7.Kenapa harus murojaah? 8.Apa itu Sima'i? 9.Cara hafal ayat panjang? 10.Apa adab menghafal?\n\nPraktik Hafalan: Hafal Al-Ikhlas, Al-Falaq, An-Nas, setor ke guru, baca tanpa mushaf, murojaah mandiri.\n\nPraktik Murojaah: Baca surah yang sudah hafal, lanjutkan ayat yang dibacakan guru, sebutkan ayat acak, gabungkan beberapa surah, perbaiki kesalahan."
    if "indikator tahfidz" in t or "indikator" in t: return f"**BAB XVI - INDIKATOR KEBERHASILAN, {n}**\n\n1.Membaca - Baca ayat benar 2.Menghafal - Mampu hafal ayat 3.Kelancaran - Baca tanpa banyak berhenti 4.Ketepatan - Tidak banyak salah lafaz 5.Tajwid - Terapkan hukum bacaan 6.Kemandirian - Mampu ulang sendiri 7.Konsistensi - Rutin murojaah 8.Adab - Sikap baik terhadap Quran"
    if "kesimpulan tahfidz" in t or "kesimpulan" in t: return f"**BAB XVII - KESIMPULAN, {n}**\n\nTahfidz = menghafal & menjaga ayat Quran lewat membaca, mendengarkan, mengulang, mengingat, menyetorkan hafalan.\n\nFaktor sukses: 1.Niat ikhlas 2.Kemampuan baca 3.Penguasaan tajwid 4.Metode tepat 5.Disiplin hafal 6.Konsisten murojaah 7.Bimbingan guru 8.Dukungan keluarga & lingkungan 9.Evaluasi berkala.\n\nPaling penting: Seimbangkan ZIYADAH (hafalan baru) + MUROJAAH (pengulangan) + TAHSIN (perbaikan bacaan). Ketiganya saling melengkapi!\n\nReferensi: Al-Quran al-Karim, Shahih Bukhari, Al-Itqan fi Ulum al-Quran, Al-Burhan fi Ulum al-Quran, Sa'dullah 9 Cara Praktis Menghafal Quran, Ahsin W. Bimbingan Praktis Menghafal Quran.\n\nTingkatan: Dasar (surah pendek, Juz 30 akhir), Menengah (perbanyak hafalan & murojaah, Juz 30 bertahap), Lanjutan (penguatan & tasmi', jaga hafalan menyeluruh)."
    return f"**Semangat Tahfidz, {n}! 🤲**\n\nKamu nanya: '{t}'\n\nKetik 'Tahfidz' buat lihat SEMUA BAB I-XVII, atau ketik: Cara hafal / Murojaah / Juz 30 / Program 30 hari"
def jawab_qori(tanya, mode):
    t = tanya.lower().strip(); n = nama
    if mode=="Iqro":
        if any(k in t for k in KATA_TAHSIN): return f"⛔ **Maaf {n}, kamu kelas IQRO!** Itu materi TAHSIN. Fokus Iqro dulu! Ketik: Iqro"
        if any(k in t for k in KATA_TAHFIDZ): return f"⛔ **Maaf {n}, kamu kelas IQRO!** Itu materi TAHFIDZ. Fokus Iqro dulu! Ketik: Iqro"
        return jawab_iqro(t,n)
    if mode=="Tahsin":
        if t in ["iqro","iqro 1","iqro 2","iqro 3","iqro 4","iqro 5","iqro 6"]: return f"⛔ **Maaf {n}, kamu kelas TAHSIN!** Udah lulus Iqro. Fokus Tahsin! Ketik: Tahsin"
        if any(k in t for k in KATA_TAHFIDZ): return f"⛔ **Maaf {n}, kamu kelas TAHSIN!** Itu materi TAHFIDZ. Fokus Tahsin dulu! Ketik: Tahsin"
        return jawab_tahsin(t,n)
    if mode=="Tahfidz":
        if any(k in t for k in KATA_IQRO): return f"⛔ **Maaf {n}, kamu kelas TAHFIDZ!** Itu materi IQRO. Fokus menghafal! Ketik: Tahfidz"
        if any(k in t for k in KATA_TAHSIN): return f"⛔ **Maaf {n}, kamu kelas TAHFIDZ!** Itu materi TAHSIN. Fokus menghafal! Ketik: Tahfidz"
        return jawab_tahfidz(t,n)
    return f"Semangat {n}!"
if st.button("Tanya Qori AI"):
    if not pertanyaan: st.warning("Tulis dulu pertanyaannya ya!")
    else: st.info(jawab_qori(pertanyaan, mode))
st.write("---")
st.write("Semoga bermanfaat. Wassalamualaikum warahmatullahi wabarakatuh")
